"""Write canonical_test.go's expected values: PyYAML 6.0.2's safe_dump(sort_keys=True,
default_flow_style=False), through proposals.normalise_body, for named cases grouped by what of the
canonical form they pin.

REGENERATE from a checkout of the last Python commit (9a11299), with PyYAML==6.0.2:
    python -I internal/pyyaml/testdata/gen_canonical.py /path/to/python-checkout > internal/pyyaml/canonical_cases_test.go
"""
import json
import sys

sys.path.insert(0, sys.argv[1])
import proposals as P  # noqa: E402

CASES = [
    # key order
    ("dict/keys-sorted", "b: 1\na: 2\nc: 3\n"),
    ("dict/nested-keys-sorted", "z: {y: 1, x: 2}\na: {d: [1, 2], c: null}\n"),
    ("dict/key-types-mixed-left-in-order", "b: 1\n1: a\na: 2\n"),
    ("dict/duplicate-keys-last-wins", "a: 1\nb: 2\na: 3\n"),
    ("dict/empty-values", "a: {}\nb: []\nc: ''\nd:\n"),
    # nested lists
    ("list/indentless-under-key", "items:\n  - a\n  - b\n"),
    ("list/of-maps", "- name: x\n  value: 1\n- name: y\n  value: [1, [2, [3]]]\n"),
    ("list/top-level-nested", "- [a, b]\n- - c\n  - d\n"),
    ("list/anchors-shared", "a: &x [1, 2]\nb: *x\n"),
    ("list/merge-key", "base: &b {x: 1, y: 2}\nderived:\n  <<: *b\n  y: 3\n"),
    # multiline strings
    ("multiline/literal", "m: |\n  line one\n  line two\n"),
    ("multiline/folded", "m: >\n  folded one\n  folded two\n"),
    ("multiline/literal-keep", "m: |+\n  keep\n\n"),
    ("multiline/quoted-with-newline", "m: \"a\\nb\"\n"),
    ("multiline/long-line-folds-at-80", "m: " + " ".join(["word"] * 40) + "\n"),
    ("multiline/long-unbreakable", "m: " + "x" * 120 + "\n"),
    # special characters and unicode escaping
    ("special/colon-space", "m: 'a: b'\n"),
    ("special/hash", "m: 'a #b'\n"),
    ("special/leading-dash", "m: '- x'\n"),
    ("special/quotes", "m: \"it's \\\"q\\\"\"\n"),
    ("special/accents", "m: café ñ\n"),
    ("special/cjk-emoji", "m: 日本 😀\n"),
    ("special/control-and-tab", "m: \"a\\tb\\x01\"\n"),
    ("special/line-separator", "m: \"a\\u2028b\"\n"),
    ("special/leading-trailing-space", "m: ' padded '\n"),
    ("special/at-and-backtick", "m: '@x'\nn: '`y'\n"),
    # numbers and other scalars that look like strings
    ("scalar/quoted-int", "m: '123'\n"),
    ("scalar/quoted-float", "m: '1.0'\n"),
    ("scalar/quoted-bools", "a: 'yes'\nb: 'no'\nc: 'on'\nd: 'true'\n"),
    ("scalar/quoted-null", "a: 'null'\nb: '~'\nc: ''\n"),
    ("scalar/quoted-date", "m: '2020-01-01'\n"),
    ("scalar/quoted-octal-hex", "a: '0o17'\nb: '0x1F'\nc: '017'\n"),
    ("scalar/plain-1e3-is-a-string", "m: 1e3\n"),
    # None/true/false spelling and numbers
    ("spelling/null-forms", "a: null\nb: ~\nc: Null\nd:\n"),
    ("spelling/bools-yaml11", "a: yes\nb: No\nc: ON\nd: off\ne: True\n"),
    ("spelling/ints", "a: 0b101\nb: 0x1F\nc: 017\nd: 1_000\ne: 190:20:30\nf: -0\n"),
    ("spelling/floats", "a: 1.5\nb: 1.5e+3\nc: .inf\nd: -.inf\ne: .nan\nf: 1e17.0\ng: 10000000000000000.0\n"),
    ("spelling/timestamps", "a: 2026-10-01\nb: 2026-10-01T10:00:00Z\nc: 2026-10-01 10:00:00.5\n"),
    ("spelling/binary", "a: !!binary aGVsbG8gd29ybGQ=\n"),
    # a real Alert proposal body
    ("k8s/alert", "apiVersion: observability.krateo.io/v1alpha1\nkind: Alert\nmetadata: {name: x, namespace: krateo-system}\n"
                  "spec: {interval: 15m, threshold: 1, thresholdType: above, where: \"Body LIKE '%x%'\"}\n"),
]

out = ["// Code generated by testdata/gen_canonical.py from PyYAML 6.0.2; DO NOT EDIT.", "", "package pyyaml", "",
       "var canonicalCases = []struct{ name, content, want string }{"]
for name, content in CASES:
    want = P.normalise_body(content, "yaml")
    out.append(f"\t{{{json.dumps(name)}, {json.dumps(content, ensure_ascii=False)}, {json.dumps(want, ensure_ascii=False)}}},")
out.append("}")
print("\n".join(out))
